import os
from taf.gnb.oam.ne3s.ws.components.base import FunctionalComponent
from taf.gnb.oam.ne3s.ws.components.connection.exceptions import NE3SRequestFailed
from taf.gnb.oam.ne3s.ws.components.SWM.v1.resources.templates import templates as swm_templates
from taf.gnb.oam.ne3s.ws.components.SWM.v1.resources.notifications.messages import (
    SWMNotificationGroup, VersionChange)
from taf.gnb.oam.ne3s.ws.components.CM.v1.CM import CMv1
from taf.gnb.oam.ne3s.ws.filter import MessageStream, MessageRule
from taf.gnb.oam.ne3s.ws.components.exceptions import OperationFailed, OperationTimeout
from taf.gnb.oam.ne3s.ws.exceptions import StreamTimeoutError


class SWMv1(FunctionalComponent):
    DEFAULT_ADAPTATION_VERSION = 'MRBTS-1900'
    STREAMS = None
    _connection = None
    SUPPORTED_NOTIFICATIONS = SWMNotificationGroup

    def __init__(self, connection):
        self._connection = connection
        self._cm = CMv1(connection=connection)
        self.swm_all_notifications = MessageStream(name="SWM.all", rule=MessageRule(condition=(VersionChange,)))
        self.STREAMS = [self.swm_all_notifications]

    def update_software(self,
                        bts_sw_path,
                        package_version,
                        adaptation_version,
                        timeout=300):
        """
        Provision operation combines the download, validation and activation
        of the plan into one asynchronous operation.

        Preconditions:
        0) Session is established
        1) Notifications are defined as `supported` in the SoC (required only on some builds)

        :param bts_sw_path: path to bts software catalog, e.g.: '/tmp/bts_sw'
        :param package_version: version of software, e.g.: '5G19_FSMK_0005_002835_000017';
                                if omitted, the program will try to extract softwareReleaseVersion
                                from the TargetBD file
        :param adaptation_version: defaults to MRBTS-1900
        :param timeout: defaults to 300 seconds

        :return: server response to the provision request
        :raises UnexpectedResponse if the server answered with status code
        other than 200
        """
        stream_name = "SWM.update_software"
        sw_update_stream = self.add_new_msg_stream(stream_name=stream_name,
                                                   msg_list=[VersionChange])

        provision_content = self.get_provision_content(
            adaptation_version=adaptation_version,
            bts_sw_path=bts_sw_path,
            package_version=package_version)

        try:
            self._cm.provision(provision_content=provision_content)
            version_change_msg = sw_update_stream.get(timeout=timeout)
            return version_change_msg.active_sw_release_ver

        except NE3SRequestFailed as e:
            err_msg = "Could not initiate software update due NE3S Request Failure with Error: {}".format(e)
            raise OperationFailed(err_msg)

        except StreamTimeoutError as e:
            err_msg = "Requested version change was not provided or done in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    def get_provision_content(self, adaptation_version, bts_sw_path, package_version):
        adaptation_version = adaptation_version or self.DEFAULT_ADAPTATION_VERSION
        provision_content = swm_templates.get_file_content('provision_message.xml', 'r')

        items = self._create_item_list(bts_sw_path, package_version)
        provision_content = provision_content.format(
            items='\n'.join(items),
            user=self._connection.connection_details.manager_id,
            password=self._connection.connection_details.manager_id,
            adaptation_version=adaptation_version
        )
        return provision_content

    def _create_item_list(self, bts_sw_path, package_version):
        sw_files = [os.path.join(d, x)
                    for d, dirs, files in os.walk(bts_sw_path)
                    for x in files]

        item_template = '<item><p name="packageURL">{url}</p>' \
                        '<p name="packageVersion">{version}</p>' \
                        '<p name="swSize">{sw_size}</p></item>'

        items = []
        for full_path in sw_files:
            package_url = '{}{}'.format(self._connection.files_url, full_path)
            sw_size = os.stat(full_path).st_size
            result = item_template.format(url=package_url,
                                          version=package_version,
                                          sw_size=sw_size)
            items.append(result)
        return items
